def solve(n):
    if n <= 2:
        return 0
    # odd-only sieve for numbers 2*i+1
    size = (n + 1)//2
    sieve = bytearray(b'\x01')*size
    sieve[0] = 0  # 1 is not prime
    if n % 2 == 1:
        sieve[-1] = 0  # exclude n itself (strictly less)
    r = int(n**0.5)+1
    for i in range(3, r, 2):
        if sieve[i//2]:
            start = i*i
            step = i
            start_idx = start//2
            sieve[start_idx:size:step] = b'\x00'*(((size-1-start_idx)//step)+1)
    return 1 + sieve.count(1)

