        return ''
    n = len(s)
    start, length = 0, 1
    for i in range(n):
        # odd-length centered at i
        l = r = i
        while l > 0 and r < n-1 and s[l-1] == s[r+1]:
            l -= 1; r += 1
        while l > 0 and r < n-1 and s[l-1] == s[r+1]:
            l -= 1; r += 1
        # better: just do expand
        pass
    # Simpler: try all centers
    def check(a, b):
        while a >= 0 and b < n and s[a] == s[b]:
            a -= 1; b += 1
        return a+1, b-a-1
    for i in range(n):
        l1, len1 = check(i, i)
        if len1 > length or (len1 == length and l1 < start):
            start, length = l1, len1
        if i+1 < n:
            l2, len2 = check(i, i+1)
            if len2 > length or (len2 == length and l2 < start):
                start, length = l2, len2
    return s[start:start+length]

